  "steps": [
    {
      "id": 1,
      "claim": "Einstein’s photoelectric equation gives the maximum kinetic energy of emitted electrons as Kₘₐₓ = h·ν – φ.",
      "evidence": "Derived from energy conservation for a photon of energy hν liberating an electron that must overcome the work function φ; experimentally confirmed.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping (retarding) potential V satisfies e·V = Kₘₐₓ.",
      "evidence": "By definition, the stopping potential is the voltage that just cancels the kinetic energy of the most energetic photoelectrons.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Therefore V = (h/e)·ν – φ/e, i.e., V is a linear function of the incident frequency ν.",
      "evidence": "Algebraic substitution of Kₘₐₓ from step 1 into the relation of step 2 and solving for V.",
      "weight": 0.30,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The linear relation is valid only for frequencies above the threshold ν₀ = φ/h; below ν₀ no electrons are emitted and V is undefined.",
      "evidence": "Experimentally, photoemission occurs only when photon energy exceeds the work function; otherwise Kₘₐₓ ≤ 0.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Thus the potential difference necessary to stop the emitted electrons is a linear function of the frequency above the threshold frequency, which matches option D.",
      "evidence": "Combines steps 3 and 4; option D states exactly this relationship.",
      "weight": 0.05,
      "depends_on": [3, 4]
    }
  ],
